<?php
session_start(); require_once '../includes/db_connect.php';
if (!isset($_SESSION['student_id'])) { header('Location: login.php'); exit(); }
require_once 'layout.php';
function resume_clean(string $text): string { return trim(preg_replace('/[ \t]+/', ' ', preg_replace('/\R{3,}/', "\n\n", html_entity_decode(strip_tags($text), ENT_QUOTES | ENT_HTML5, 'UTF-8')))); }
function resume_docx(string $path): string { if (!class_exists('ZipArchive')) throw new RuntimeException('DOCX reading requires the PHP Zip extension.'); $zip=new ZipArchive(); if ($zip->open($path)!==true) throw new RuntimeException('The Word document could not be opened.'); $xml=$zip->getFromName('word/document.xml'); $zip->close(); if ($xml===false || strlen($xml)>5*1024*1024) throw new RuntimeException('This is not a valid or safely sized DOCX document.'); return resume_clean(str_replace(['</w:p>','</w:tr>','<w:tab/>'],["\n","\n","\t"],$xml)); }
function resume_pdf(string $path): string { $pdf=file_get_contents($path); if ($pdf===false || !str_starts_with($pdf,'%PDF-')) throw new RuntimeException('This is not a valid PDF file.'); $text=''; preg_match_all('/BT(.*?)ET/s',$pdf,$blocks); foreach($blocks[1] as $block){preg_match_all('/\((?:\\.|[^\\)])*\)/s',$block,$strings);foreach($strings[0] as $s)$text.=preg_replace('/\\([()\\])/','$1',substr($s,1,-1)).' ';} if(trim($text)===''){preg_match_all('/stream\r?\n(.*?)\r?\nendstream/s',$pdf,$streams);foreach($streams[1] as $stream){$decoded=@gzuncompress($stream);if($decoded===false&&function_exists('zlib_decode'))$decoded=@zlib_decode($stream);if(!$decoded)continue;preg_match_all('/\((?:\\.|[^\\)])*\)/s',$decoded,$strings);foreach($strings[0] as $s)$text.=preg_replace('/\\([()\\])/','$1',substr($s,1,-1)).' ';}} $text=resume_clean($text);if(mb_strlen($text)<20)throw new RuntimeException('Text could not be extracted. Upload a text-based PDF (not a scanned image) or DOCX.');return $text; }
function resume_where(string $text): string { foreach(['Skills','Experience','Projects','Education','Summary'] as $heading) if(preg_match('/^.*'.$heading.'.*$/mi',$text,$m))return trim($m[0]); return 'Not found in the uploaded resume'; }
function resume_feedback(string $resume,array $missing): array { $items=[];$add=function($weakness,$location,$impact)use(&$items){$items[]=['weakness'=>$weakness,'location'=>$location,'impact'=>$impact];};if(!preg_match('/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i',$resume))$add('No professional email was detected.','Contact details — not found','Recruiters and ATS systems may not have a reliable contact method.');if(!preg_match('/(?:\+?\d[\s.-]?){8,}/',$resume))$add('No phone number was detected.','Contact details — not found','A missing contact number can slow recruiter follow-up.');if(mb_strlen($resume)<450)$add('The extracted content is very brief.','Whole document','Short resumes often lack enough skills, projects, and evidence for ATS matching.');if(!preg_match('/\b(skills?|technical skills|technologies)\b/i',$resume))$add('No clearly labelled skills section was found.','Skills section — not found','ATS parsers use clear section labels to recognise keywords consistently.');if(!preg_match('/\b(built|developed|implemented|created|designed|improved|led|deployed|optimized)\b/i',$resume))$add('Few action-oriented achievement statements were detected.',resume_where($resume),'Passive wording makes your contribution harder to assess.');if(!preg_match('/\b\d+(?:\.\d+)?\s*(?:%|users|projects|days|months|x)\b/i',$resume))$add('No measurable outcomes were detected.',resume_where($resume),'Metrics make claims more credible and show the scale of your impact.');foreach(array_slice($missing,0,5) as $word)$add('Target keyword is missing: '.$word.'.',resume_where($resume),'If truthful for your experience, its absence can lower your match for this job description.');return $items?:[['weakness'=>'No major structural weakness was detected.','location'=>'Whole document','impact'=>'Keep tailoring your wording truthfully to each role.']]; }
$name=$_SESSION['student_name']??'Your Name';$role='';$jd='';$resume='';$uploadedName='';$missing=[];$score=null;$feedback=[];$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){$name=trim($_POST['resume_name']??$name);$role=trim($_POST['job_role']??'');$jd=trim($_POST['job_description']??'');$file=$_FILES['resume_file']??null;if(!$file||$file['error']!==UPLOAD_ERR_OK)$error='Choose a PDF or DOCX resume to analyze.';elseif($file['size']>5*1024*1024)$error='The resume must be 5 MB or smaller.';else{$ext=strtolower(pathinfo($file['name'],PATHINFO_EXTENSION));if(!in_array($ext,['pdf','docx'],true)||!is_uploaded_file($file['tmp_name']))$error='Only PDF and DOCX files are accepted.';else try{$resume=$ext==='pdf'?resume_pdf($file['tmp_name']):resume_docx($file['tmp_name']);$uploadedName=basename($file['name']);}catch(RuntimeException $e){$error=$e->getMessage();}}if(!$error){preg_match_all('/\b[a-z][a-z+#.\-]{2,}\b/i',strtolower($jd),$matches);$stop=['the','and','with','for','that','this','are','from','your','will','have','years','year','job','role','work','our','you','their','but','not','skills','skill','using','into','about','team','ability','experience','responsibilities','requirements'];$freq=array_count_values(array_filter($matches[0],fn($word)=>!in_array($word,$stop,true)));arsort($freq);$keywords=array_slice(array_keys($freq),0,18);foreach($keywords as $word)if(stripos($resume,$word)===false)$missing[]=$word;$score=$keywords?(int)round((count($keywords)-count($missing))/count($keywords)*100):null;$feedback=resume_feedback($resume,$missing);}}
student_page_start($conn,'Resume Studio','resume'); ?>
