<section class="page-heading"><h1>Resume file analysis</h1><p>Upload your PDF or DOCX resume for a private ATS review. Files are not stored.</p></section><div class="resume-grid"><section class="card portal-card no-print"><form method="post" enctype="multipart/form-data"><div class="two-col"><div class="input-group"><label for="resume_name">Your name</label><input class="form-control" id="resume_name" name="resume_name" value="<?= htmlspecialchars($name) ?>"></div><div class="input-group"><label for="job_role">Target role</label><input class="form-control" id="job_role" name="job_role" value="<?= htmlspecialchars($role) ?>" placeholder="e.g. PHP Developer"></div></div><div class="input-group"><label for="resume_file">Resume file (PDF or DOCX, max 5 MB)</label><input class="form-control" id="resume_file" type="file" name="resume_file" accept=".pdf,.docx,application/pdf,application/vnd.openxmlformats-officedocument.wordprocessingml.document" required></div><div class="input-group"><label for="job_description">Job description for ATS match</label><textarea class="form-control" id="job_description" name="job_description" placeholder="Paste the complete job description here."><?= htmlspecialchars($jd) ?></textarea></div><button class="btn" type="submit">Analyze uploaded resume</button><?php if($resume): ?> <button class="btn" type="button" onclick="window.print()">Print / save PDF</button><?php endif; ?></form><?php if($error): ?><p class="error" style="margin-top:18px"><?= htmlspecialchars($error) ?></p><?php endif; ?><?php if($resume): ?><div class="result-box"><h3><?= htmlspecialchars($uploadedName) ?> analyzed<?= $score!==null?' · ATS keyword match: '.$score.'%':'' ?></h3><div class="feedback-list"><?php foreach($feedback as $item): ?><article class="feedback-item"><strong>What: </strong><?= htmlspecialchars($item['weakness']) ?><br><strong>Where: </strong><?= htmlspecialchars($item['location']) ?><br><strong>Why it matters: </strong><?= htmlspecialchars($item['impact']) ?></article><?php endforeach; ?></div></div><?php endif; ?></section><article class="resume-preview"><h1><?= htmlspecialchars($name) ?></h1><?php if($role): ?><p><?= htmlspecialchars($role) ?></p><?php endif; ?><h2>Uploaded resume preview</h2><pre><?= htmlspecialchars($resume?:'Upload a PDF or DOCX file to preview its extracted text here.') ?></pre></article></div><?php student_page_end(); ?>
